export const iconsMap: Record<string, string> = icons.reduce((acc, icon) => {
  acc[icon.name] = icon.svg;
  return acc;
}, {} as Record<string, string>);

export const iconCategories: string[] = [...new Set(icons.map(i => i.category))];
